import { ForbiddenException, Injectable, NotFoundException } from '@nestjs/common';
import { Membership, Prisma, LeaveApproval, RequestStatus } from '@prisma/client';
import { Database } from '../database.module';
import { audit, dateOnly, dateString, decisionComment, DecisionDto, fail, localDate, mayRead, privileged, selfEmployee } from '../common/domain';
import { PageDto, paginated } from '../common/page.dto';
import { GrantDto, LeaveDto, LeavePolicyDto } from './leave.dto';
const pending:RequestStatus[]=['PENDING_MANAGER','PENDING_HR'];
export function workingDays(start:Date,end:Date,days:number[],holidays:{startDate:Date;endDate:Date}[]) {
 let result=0;
 for(let at=start.getTime();at<=end.getTime();at+=86400000) {
  const d=new Date(at);
  if(days.includes(d.getUTCDay())&&!holidays.some(h=>h.startDate<=d&&h.endDate>=d)) result++;
 }
 return result;
}
@Injectable()
export class LeaveService {
 constructor(private db:Database){}
 async policies(m:Membership,q:PageDto) {
  const where={companyId:m.companyId};
  const [data,total]=await this.db.$transaction([this.db.leavePolicy.findMany({where,orderBy:{code:'asc'},skip:(q.page-1)*q.pageSize,take:q.pageSize}),this.db.leavePolicy.count({where})]);
  return paginated(data,total,q);
 }
 async createPolicy(m:Membership,d:LeavePolicyDto) {
  if(d.effectiveTo&&d.effectiveTo<d.effectiveFrom) fail('INVALID_DATES','Policy end precedes start.');
  return this.db.$transaction(async tx=>{
   const data=await tx.leavePolicy.create({data:{...d,companyId:m.companyId,effectiveFrom:dateOnly(d.effectiveFrom),effectiveTo:d.effectiveTo?dateOnly(d.effectiveTo):null}});
   await audit(tx,m,'LEAVE_POLICY_CREATED',data.id); return {data};
  });
 }
 async grant(m:Membership,d:GrantDto) {
  return this.db.$transaction(async tx=>{
   const employee=await tx.employee.findUnique({where:{companyId_id:{companyId:m.companyId,id:d.employeeId}}});
   const policy=await tx.leavePolicy.findUnique({where:{companyId_id:{companyId:m.companyId,id:d.policyId}}});
   if(!employee||!policy) throw new NotFoundException();
   const key='grant:'+d.idempotencyKey;
   const old=await tx.leaveLedger.findUnique({where:{companyId_idempotencyKey:{companyId:m.companyId,idempotencyKey:key}}});
   if(old) {
    if(old.employeeId!==d.employeeId||old.policyId!==d.policyId||old.year!==d.year||!old.days.equals(d.days)) fail('IDEMPOTENCY_CONFLICT','Key was used for another grant.',409);
    return {data:old};
   }
   const data=await tx.leaveLedger.create({data:{companyId:m.companyId,employeeId:d.employeeId,policyId:d.policyId,year:d.year,days:d.days,kind:'ADJUSTMENT',reason:d.reason,idempotencyKey:key}});
   await audit(tx,m,'LEAVE_BALANCE_ADJUSTED',data.id); return {data};
  },{isolationLevel:'Serializable'});
 }
 async balance(m:Membership) {
  const e=await selfEmployee(this.db,m);
  const groups=await this.db.leaveLedger.groupBy({by:['policyId','year'],where:{companyId:m.companyId,employeeId:e.id},_sum:{days:true}});
  return {data:groups.map(g=>({policyId:g.policyId,year:g.year,balance:g._sum.days?.toFixed(2)??'0.00'}))};
 }
 async create(m:Membership,d:LeaveDto) {
  return this.db.$transaction(async tx=>{
   const employee=await selfEmployee(tx,m);
   const policy=await tx.leavePolicy.findFirst({where:{id:d.policyId,companyId:m.companyId,active:true}});
   if(!policy) throw new NotFoundException('Leave policy not found.');
   const start=dateOnly(d.startDate),end=dateOnly(d.endDate);
   if(end<start||start.getUTCFullYear()!==end.getUTCFullYear()) fail('INVALID_DATES','Use ordered dates within one calendar year.');
   if(start<employee.joinedDate||start<policy.effectiveFrom||(policy.effectiveTo&&end>policy.effectiveTo)) fail('LEAVE_INELIGIBLE','Dates are outside employment or policy eligibility.');
   const company=await tx.company.findUniqueOrThrow({where:{id:m.companyId}});
   const today=dateOnly(localDate(new Date(),company.timezone));
   if(start.getTime()<today.getTime()+policy.noticeDays*86400000) fail('LEAVE_NOTICE_REQUIRED','Minimum advance notice has not been met.');
   if(!employee.scheduleId) fail('SCHEDULE_REQUIRED','Assign a work schedule before applying for leave.');
   const schedule=await tx.workSchedule.findFirst({where:{id:employee.scheduleId,companyId:m.companyId,active:true}});
   if(!schedule||start<schedule.effectiveFrom||(schedule.effectiveTo&&end>schedule.effectiveTo)) fail('SCHEDULE_REQUIRED','No schedule covers these dates.');
   const location=employee.locationId?await tx.workLocation.findFirst({where:{id:employee.locationId,companyId:m.companyId}}):null;
   const holidays=await tx.publicHoliday.findMany({where:{companyId:m.companyId,active:true,startDate:{lte:end},endDate:{gte:start}}});
   const days=workingDays(start,end,schedule.workingDays,holidays.filter(h=>!h.states.length||(location&&h.states.includes(location.state))));
   if(!days) fail('NO_WORKING_DAYS','The selected range has no working days.');
   if(d.halfDay&&(!policy.allowHalfDay||d.startDate!==d.endDate||days!==1)) fail('HALF_DAY_NOT_ALLOWED','Half day requires one working date and a policy that allows it.');
   if(['MANAGER','MANAGER_HR'].includes(policy.approval)&&!employee.managerId) fail('MANAGER_REQUIRED','Assign a reporting manager first.');
   const data=await tx.leaveRequest.create({data:{companyId:m.companyId,employeeId:employee.id,policyId:policy.id,startDate:start,endDate:end,halfDay:d.halfDay,days:d.halfDay?'0.50':String(days),reason:d.reason,managerId:employee.managerId,approval:policy.approval,paid:policy.paid}});
   await audit(tx,m,'LEAVE_DRAFT_CREATED',data.id); return {data};
  },{isolationLevel:'Serializable'});
 }
 async list(m:Membership,q:PageDto,all=false) {
  const employeeId=all?undefined:(await selfEmployee(this.db,m)).id;
  const where={companyId:m.companyId,employeeId};
  const [data,total]=await this.db.$transaction([this.db.leaveRequest.findMany({where,orderBy:{createdAt:'desc'},skip:(q.page-1)*q.pageSize,take:q.pageSize}),this.db.leaveRequest.count({where})]);
  return paginated(data,total,q);
 }
 async available(tx:Prisma.TransactionClient,row:{companyId:string;employeeId:string;policyId:string;startDate:Date;id:string;days:Prisma.Decimal}) {
  const year=row.startDate.getUTCFullYear();
  const sum=await tx.leaveLedger.aggregate({where:{companyId:row.companyId,employeeId:row.employeeId,policyId:row.policyId,year},_sum:{days:true}});
  const reserved=await tx.leaveRequest.aggregate({where:{companyId:row.companyId,employeeId:row.employeeId,policyId:row.policyId,status:{in:pending},id:{not:row.id},startDate:{gte:new Date(Date.UTC(year,0,1)),lt:new Date(Date.UTC(year+1,0,1))}},_sum:{days:true}});
  if(new Prisma.Decimal(sum._sum.days??0).minus(reserved._sum.days??0).lessThan(row.days)) fail('LEAVE_BALANCE_INSUFFICIENT','Insufficient available leave balance.');
 }
 async consume(tx:Prisma.TransactionClient,row: {id:string;companyId:string;employeeId:string;policyId:string;startDate:Date;days:Prisma.Decimal},reverse=false) {
  await tx.leaveLedger.create({data:{companyId:row.companyId,employeeId:row.employeeId,policyId:row.policyId,requestId:row.id,year:row.startDate.getUTCFullYear(),days:reverse?row.days:row.days.negated(),kind:reverse?'REVERSAL':'USAGE',reason:reverse?'Approved leave cancelled':'Leave approved',idempotencyKey:(reverse?'reverse:':'usage:')+row.id}});
 }
 async submit(m:Membership,id:string) {
  return this.db.$transaction(async tx=>{
   const row=await tx.leaveRequest.findUnique({where:{companyId_id:{companyId:m.companyId,id}}});
   if(!row) throw new NotFoundException();
   if(row.employeeId!==(await selfEmployee(tx,m)).id) throw new ForbiddenException();
   if(row.status!=='DRAFT') fail('INVALID_STATE','Only drafts can be submitted.',409);
   const overlap=await tx.leaveRequest.findFirst({where:{companyId:m.companyId,employeeId:row.employeeId,id:{not:id},status:{in:[...pending,'APPROVED']},startDate:{lte:row.endDate},endDate:{gte:row.startDate}}});
   if(overlap) fail('LEAVE_OVERLAP','Another application already covers these dates.',409);
   if(row.paid) await this.available(tx,row);
   const status:RequestStatus=row.approval==='NO_APPROVAL'?'APPROVED':row.approval==='HR_ONLY'?'PENDING_HR':'PENDING_MANAGER';
   const data=await tx.leaveRequest.update({where:{companyId_id:{companyId:m.companyId,id}},data:{status}});
   if(status==='APPROVED'&&row.paid) await this.consume(tx,row);
   await audit(tx,m,'LEAVE_SUBMITTED',id); return {data};
  },{isolationLevel:'Serializable'});
 }
 async decide(m:Membership,id:string,d:DecisionDto) {
  decisionComment(d);
  return this.db.$transaction(async tx=>{
   const row=await tx.leaveRequest.findUnique({where:{companyId_id:{companyId:m.companyId,id}}});
   if(!row) throw new NotFoundException();
   if(!pending.includes(row.status)) fail('INVALID_STATE','Request is not awaiting a decision.',409);
   if(m.employeeId===row.employeeId) throw new ForbiddenException('You cannot approve your own request.');
   const allowed=row.status==='PENDING_MANAGER'?m.employeeId===row.managerId||privileged(m,['OWNER']):privileged(m,['OWNER','HR']);
   if(!allowed) throw new ForbiddenException();
   const status:RequestStatus=d.decision==='REJECT'?'REJECTED':row.status==='PENDING_MANAGER'&&row.approval==='MANAGER_HR'?'PENDING_HR':'APPROVED';
   if(status==='APPROVED'&&row.paid){await this.available(tx,row);await this.consume(tx,row);}
   const data=await tx.leaveRequest.update({where:{companyId_id:{companyId:m.companyId,id}},data:{status,decisionComment:d.comment,decidedBy:m.userId,decidedAt:new Date()}});
   await audit(tx,m,'LEAVE_'+d.decision,id);return {data};
  },{isolationLevel:'Serializable'});
 }
 async cancel(m:Membership,id:string) {
  return this.db.$transaction(async tx=>{
   const row=await tx.leaveRequest.findUnique({where:{companyId_id:{companyId:m.companyId,id}}});
   if(!row) throw new NotFoundException(); mayRead(m,row.employeeId);
   if(['CANCELLED','REJECTED'].includes(row.status)) fail('INVALID_STATE','Request cannot be cancelled.',409);
   const company=await tx.company.findUniqueOrThrow({where:{id:m.companyId}});
   if(row.startDate<dateOnly(localDate(new Date(),company.timezone))) fail('LEAVE_ALREADY_STARTED','Past leave requires an HR correction workflow.');
   if(row.status==='APPROVED'&&row.paid) await this.consume(tx,row,true);
   const data=await tx.leaveRequest.update({where:{companyId_id:{companyId:m.companyId,id}},data:{status:'CANCELLED'}});
   await audit(tx,m,'LEAVE_CANCELLED',id);return {data};
  },{isolationLevel:'Serializable'});
 }
 async pending(m:Membership,q:PageDto) {
  const where:Prisma.LeaveRequestWhereInput={companyId:m.companyId,status:{in:pending},...(privileged(m,['OWNER'])?{}: {OR:[...(privileged(m,['HR'])?[{status:'PENDING_HR' as const}]:[]),...(m.employeeId?[{status:'PENDING_MANAGER' as const,managerId:m.employeeId}]:[])]})};
  const [data,total]=await this.db.$transaction([this.db.leaveRequest.findMany({where,skip:(q.page-1)*q.pageSize,take:q.pageSize,orderBy:{createdAt:'asc'}}),this.db.leaveRequest.count({where})]);return paginated(data,total,q);
 }
}

